  pregnancyDateRequired: 'Соңғы етеккір күнін көрсетіңіз.', pregnancyFutureDate: 'Күн болашақта болмауы керек.',
  pregnancyWeekResult: 'Болжамды мерзім: {weeks} апта {days} күн.', estimatedDueDate: 'Болжамды босану күні',
