function calculatePregnancy() {
  const input = document.querySelector('#pregnancyLastPeriod');
  const result = document.querySelector('#pregnancyResult');
  result.hidden = false;
  const validationError = pregnancyInputError();
  if (validationError) {
    result.textContent = validationError;
    document.querySelector('#pregnancyProgress').hidden = true;
    return;
  }
  const start = dateFromKey(input.value);
  const current = dateFromKey(dateKey(today));
  const elapsedDays = Math.floor((current - start) / 86400000);
  if (!Number.isFinite(elapsedDays) || elapsedDays < 0) {
    result.textContent = t('pregnancyFutureDate');
    document.querySelector('#pregnancyProgress').hidden = true;
    return;
  }
  const weeks = Math.floor(elapsedDays / 7);
  const extraDays = elapsedDays % 7;
  const trimester = weeks <= 13 ? 1 : weeks <= 27 ? 2 : 3;
  const remainingWeeks = Math.max(0, 40 - weeks);
  const dueDate = addDays(start, 280);
  const progress = Math.min(100, Math.round((elapsedDays / 280) * 100));
  result.textContent = t('pregnancyWeekResult').replace('{weeks}', weeks).replace('{days}', extraDays);
  document.querySelector('#pregnancyTrimester').textContent = t('trimester').replace('{number}', trimester);
  document.querySelector('#pregnancyWeekTitle').textContent = t('pregnancyWeekResult').replace('{weeks}', weeks).replace('{days}', extraDays);
  document.querySelector('#pregnancyRemaining').textContent = t('pregnancyRemaining').replace('{weeks}', remainingWeeks);
  document.querySelector('#pregnancyWeekCircle').textContent = weeks + '/40';
  document.querySelector('#pregnancyDueDate').textContent = formatDate(dateKey(dueDate)) + ' ' + dueDate.getFullYear();
  document.querySelector('#pregnancyCircle').style.setProperty('--pregnancy-progress', progress + '%');
  document.querySelector('#pregnancyProgress').hidden = false;
}

async function saveCycleSettingsForm(event) {
  event.preventDefault();
  const cycleLength = Number(document.querySelector('#preferredCycleLength').value);
  const periodLength = Number(document.querySelector('#preferredPeriodLength').value);
  const reminderDays = Number(document.querySelector('#reminderDays').value);
  const settingsError = validateCycleSettings(cycleLength, periodLength, reminderDays);
  showFormError(document.querySelector('#cycleSettingsMessage'), settingsError);
  if (settingsError) return;
  state.preferences = {
    useCustom: true,
    cycleLength: cycleLength,
    periodLength: periodLength,
    reminderDays: reminderDays
  };
  savePreferences();
  await loadCalendarForecast(); renderForecastSummary(); renderCalendar(); renderCharts(); maybeSendCycleNotification(true);
  setModal(cycleSettingsModal, false); showToast(t('settingsSaved'));
}

function closeOnboarding(openEditor) {
  localStorage.setItem('sana-onboarding-done', 'true');
  setModal(onboardingModal, false);
  if (openEditor) openPeriodEditor(dateKey(today));
}

function openClearDataDialog() {
  setModal(clearDataModal, true, '#cancelClearData');
}

function closeClearDataDialog() {
  setModal(clearDataModal, false);
  document.querySelector('#clearData').focus();
}

async function confirmClearData() {
  if (clearDataModal.hidden) return;
  closeClearDataDialog();
  await clearLocalData();
}

async function clearLocalData() {
  let clearedOnServer = false;
  try {
    await apiRequest('/api/data', { method: 'DELETE' });
    clearedOnServer = true;
  } catch (error) {
    if (state.authToken || state.trackerOnline) { showToast(t('trackingSaveError')); return; }
    // GitHub Pages has no backend, so local cleanup below is enough there.
  }
  ['sana-logs', 'sana-periods', 'sana-notifications', 'sana-private-notes'].forEach(function (key) {
    localStorage.removeItem(key);
  });
  state.logs.clear();
  state.periods = [];
  state.privateNotes = {};
  localStorage.removeItem(trackingCacheKey());
  state.tracking = SanaTracking.normalize(null);
  if (!clearedOnServer) cacheTracking(true);
  await loadCalendarForecast();
  await loadSummary();
  renderForecastSummary();
  renderCalendar();
  renderCharts();
  updateSelectedDate();
  showToast(t('cleared'));
}

function renderChat() {
  const container = document.querySelector('#chatMessages');
  if (!state.chatMessages.length) {
    state.chatMessages.push({ role: 'assistant', content: t('chatWelcome'), welcome: true });
  } else if (state.chatMessages.length === 1 && state.chatMessages[0].welcome) {
    state.chatMessages[0].content = t('chatWelcome');
  }

  container.innerHTML = '';
  state.chatMessages.forEach(function (message) {
    const bubble = document.createElement('div');
    bubble.className = 'chat-message ' + message.role;
    bubble.textContent = message.content;
    container.appendChild(bubble);
  });
  container.scrollTop = container.scrollHeight;
}

function setOllamaStatus(online) {
  const status = document.querySelector('#ollamaStatus');
  status.textContent = t(online ? 'ollamaOnline' : 'ollamaOffline');
  status.classList.toggle('online', online);
}

async function checkOllama() {
  try {
    const response = await fetch(ollamaBaseUrl + '/api/tags');
    if (!response.ok) throw new Error('Ollama error: ' + response.status);
    const data = await response.json();
    const models = Array.isArray(data.models) ? data.models.map(function (model) {
      return model.name || model.model;
    }).filter(Boolean) : [];
    const input = document.querySelector('#ollamaModel');
    if (models.length && !models.includes(input.value.trim())) {
      input.value = models[0];
      localStorage.setItem('sana-ollama-model', models[0]);
    }
    setOllamaStatus(true);
  } catch (error) {
    setOllamaStatus(false);
  }
}

async function sendChatMessage(event) {
  event.preventDefault();
  const input = document.querySelector('#chatInput');
  const button = document.querySelector('#chatSend');
  const question = input.value.trim();
  if (!question || question.length > 1000) {
    showToast(t('invalidChat'));
    return;
  }
  if (button.disabled) return;
  const chatToken = state.authToken;

  state.chatMessages.push({ role: 'user', content: question });
  input.value = '';
  renderChat();
  button.disabled = true;
  document.querySelector('#clearChatHistory').disabled = true;
  button.textContent = t('sending');

  const model = document.querySelector('#ollamaModel').value.trim() || 'qwen2.5:3b';
  localStorage.setItem('sana-ollama-model', model);
  const messages = [
    {
      role: 'system',
      content: 'You are Sana, a direct and down-to-earth wellbeing assistant. Reply naturally in the same language as the user. Start with the answer immediately: do not greet the user, introduce yourself, repeat their name, or add filler phrases. Keep responses concise, practical, and conversational, with occasional dry humor only when it fits. Do not sound robotic, overly cheerful, or needlessly rude. Never insult, humiliate, threaten, or discriminate. Give only general educational wellbeing information, never diagnose, and clearly recommend professional medical care for dangerous or alarming symptoms.'
    }
  ].concat(state.chatMessages.filter(function (message) {
    return !message.welcome;
  }).map(function (message) {
    return { role: message.role, content: message.content };
  }));

  try {
    const response = await fetch(ollamaBaseUrl + '/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: model, messages: messages, stream: false })
    });
    if (!response.ok) throw new Error('Ollama error: ' + response.status);
    const data = await response.json();
    if (chatToken !== state.authToken) return;
    if (!data.message || !data.message.content) throw new Error('Empty answer');
    state.chatMessages.push({ role: 'assistant', content: data.message.content });
    if (chatToken) {
      try {
        await apiRequest('/api/chat/turns', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ question: question, answer: data.message.content })
        });
        if (chatToken === state.authToken) document.querySelector('#chatHistoryStatus').textContent = t('historySaved');
      } catch (error) {
        if (chatToken === state.authToken) document.querySelector('#chatHistoryStatus').textContent = t('historySaveError');
      }
    }
    setOllamaStatus(true);
  } catch (error) {
    if (chatToken !== state.authToken) return;
    state.chatMessages.push({ role: 'assistant', content: t('chatOffline') });
    setOllamaStatus(false);
  } finally {
    button.disabled = false;
    document.querySelector('#clearChatHistory').disabled = false;
    button.textContent = t('send');
    renderChat();
  }
}

function bindEvents() {
  document.querySelector('#trackingModeButton').addEventListener('click', openPregnancyMode);
  document.querySelector('#calendarPregnancySettings').addEventListener('click', openPregnancyMode);
  document.querySelector('#activatePregnancy').addEventListener('click', activatePregnancyMode);
  document.querySelector('#endPregnancy').addEventListener('click', function () {
    document.querySelector('#endPregnancyConfirm').hidden = false;
    document.querySelector('#cancelEndPregnancy').focus();
  });
  document.querySelector('#cancelEndPregnancy').addEventListener('click', function () {
    document.querySelector('#endPregnancyConfirm').hidden = true;
    document.querySelector('#endPregnancy').focus();
  });
  document.querySelector('#confirmEndPregnancy').addEventListener('click', finishPregnancyMode);
  document.querySelector('#pregnancyLastPeriod').addEventListener('change', function () {
    document.querySelector('#trackingMessage').textContent = '';
    document.querySelector('#calculatePregnancy').click();
  });
  document.querySelector('#calendarToday').addEventListener('click', goToToday);
  document.querySelector('#selectPeriodDays').addEventListener('click', function () {
    if (isPregnancyMode()) return;
    state.periodSelection = { start: null, end: null }; renderCalendar();
  });
  document.querySelector('#cancelPeriodSelection').addEventListener('click', function () { state.periodSelection = null; renderCalendar(); });
  document.querySelector('#continuePeriodSelection').addEventListener('click', function () {
    const selection = state.periodSelection;
    if (!selection || !selection.start || isPregnancyMode()) return;
    openPeriodEditor(selection.start);
    document.querySelector('#periodEnd').value = selection.end || selection.start;
    state.periodSelection = null; renderCalendar();
  });
  pregnancyModal.addEventListener('keydown', function (event) {
    if (event.key !== 'Tab') return;
    const fields = Array.from(pregnancyModal.querySelectorAll('button:not([disabled]), input:not([disabled])')).filter(function (node) { return node.getClientRects().length; });
    const first = fields[0]; const last = fields[fields.length - 1];
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
  });
  document.querySelectorAll('[data-view]').forEach(function (button) {
    button.addEventListener('click', function () {
      setView(button.dataset.view);
    });
  });

  document.querySelectorAll('[data-go]').forEach(function (button) {
    button.addEventListener('click', function () {
      if (button.dataset.go === 'log') openLog();
      else setView(button.dataset.go);
    });
  });

  document.querySelectorAll('.lang').forEach(function (button) {
    button.addEventListener('click', function () {
      applyLanguage(button.dataset.lang);
    });
  });

  document.querySelector('#profileButton').addEventListener('click', function () {
    setView('profile');
  });
  document.querySelector('#profileLanguageButton').addEventListener('click', function () {
    applyLanguage(state.lang === 'kk' ? 'ru' : 'kk');
  });
  document.querySelector('#notificationsButton').addEventListener('click', toggleNotifications);
  document.querySelector('#cycleSettingsButton').addEventListener('click', openCycleSettings);
  document.querySelector('#pregnancyButton').addEventListener('click', openPregnancyMode);
  document.querySelector('#homePregnancyButton').addEventListener('click', openPregnancyMode);
  document.querySelector('#latePregnancyButton').addEventListener('click', openPregnancyMode);
  document.querySelector('#privateNoteButton').addEventListener('click', function () { openPrivateNoteEditor(selectedDateKey()); });
  document.querySelector('#closePrivateNote').addEventListener('click', function () { setModal(document.querySelector('#privateNoteModal'), false); });
  document.querySelector('#privateNoteForm').addEventListener('submit', savePrivateNote);
  document.querySelector('#deletePrivateNote').addEventListener('click', deletePrivateNote);
  document.querySelector('#privacyButton').addEventListener('click', togglePrivacy);
  document.querySelector('#clearData').addEventListener('click', openClearDataDialog);
  document.querySelector('#cancelClearData').addEventListener('click', closeClearDataDialog);
  document.querySelector('#confirmClearData').addEventListener('click', confirmClearData);
  clearDataModal.addEventListener('click', function (event) {
    if (event.target === clearDataModal) closeClearDataDialog();
  });
  clearDataModal.addEventListener('keydown', function (event) {
    if (event.key !== 'Tab') return;
    const cancel = document.querySelector('#cancelClearData');
    const confirm = document.querySelector('#confirmClearData');
    if (event.shiftKey && document.activeElement === cancel) {
      event.preventDefault(); confirm.focus();
    } else if (!event.shiftKey && document.activeElement === confirm) {
      event.preventDefault(); cancel.focus();
    }
  });
  document.querySelector('#historyAddPeriod').addEventListener('click', function () { openPeriodEditor(dateKey(today)); });
  document.querySelector('#logoutButton').addEventListener('click', logout);

  document.querySelectorAll('[data-open-register]').forEach(function (button) {
    button.addEventListener('click', function () {
      setModal(registerModal, true, '#registerName');
    });
  });
  document.querySelectorAll('[data-open-login]').forEach(function (button) {
    button.addEventListener('click', function () {
      setModal(loginModal, true, '#loginEmail');
    });
  });
  document.querySelector('#closeRegister').addEventListener('click', function () {
    setModal(registerModal, false);
  });
  document.querySelector('#closeLogin').addEventListener('click', function () {
    setModal(loginModal, false);
  });
  document.querySelector('#closePeriodModal').addEventListener('click', function () { setModal(periodModal, false); });
  document.querySelector('#closeCycleSettings').addEventListener('click', function () { setModal(cycleSettingsModal, false); });
  document.querySelector('#closePregnancy').addEventListener('click', function () { setModal(pregnancyModal, false); });
  [registerModal, loginModal, periodModal, cycleSettingsModal, pregnancyModal, document.querySelector('#privateNoteModal')].forEach(function (modal) {
    modal.addEventListener('click', function (event) {
      if (event.target === modal) setModal(modal, false);
    });
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      if (!clearDataModal.hidden) closeClearDataDialog();
      setModal(registerModal, false);
      setModal(loginModal, false);
      setModal(periodModal, false);
      setModal(cycleSettingsModal, false);
      setModal(pregnancyModal, false);
      setModal(document.querySelector('#privateNoteModal'), false);
      setModal(onboardingModal, false);
    }
  });

  document.querySelector('#registerForm').addEventListener('submit', register);
  document.querySelector('#loginForm').addEventListener('submit', login);
  document.querySelector('#periodForm').addEventListener('submit', savePeriodDetails);
  document.querySelector('#deletePeriodButton').addEventListener('click', deleteEditedPeriod);
  document.querySelector('#cycleSettingsForm').addEventListener('submit', saveCycleSettingsForm);
  document.querySelector('#calculatePregnancy').addEventListener('click', calculatePregnancy);
  document.querySelector('#saveLog').addEventListener('click', saveLog);
  document.querySelector('#logPeriodButton').addEventListener('click', function () {
    if (isPregnancyMode()) { state.logDate = dateKey(today); fillLogForm(state.logDate); setView('log'); }
    else openPeriodEditor(dateKey(today));
  });
  document.querySelector('#markSelectedPeriodButton').addEventListener('click', function () {
    openPeriodEditor(selectedDateKey());
  });
  document.querySelector('#addPeriodButton').addEventListener('click', function () { openPeriodEditor(selectedDateKey()); });

  document.querySelectorAll('.mood').forEach(function (button) {
    button.addEventListener('click', function () {
      state.mood = button.dataset.mood;
      syncLogChoices();
    });
  });
  document.querySelectorAll('#moodChoices button').forEach(function (button) {
    button.addEventListener('click', function () {
      state.mood = button.dataset.value;
      syncLogChoices();
    });
  });
  document.querySelectorAll('#energyChoices button').forEach(function (button) {
    button.addEventListener('click', function () {
      state.energy = button.dataset.value;
      syncLogChoices();
    });
  });
  document.querySelectorAll('#symptomChoices button').forEach(function (button) {
    button.addEventListener('click', function () {
      const value = button.dataset.value;
      if (value === 'none') {
        state.symptoms = ['none'];
      } else {
        state.symptoms = state.symptoms.filter(function (item) {
          return item !== 'none';
        });
        if (state.symptoms.includes(value)) {
          state.symptoms = state.symptoms.filter(function (item) {
            return item !== value;
          });
        } else {
          state.symptoms.push(value);
        }
        if (!state.symptoms.length) state.symptoms = ['none'];
      }
      syncLogChoices();
    });
  });

  document.querySelector('#prevMonth').addEventListener('click', async function () {
    state.shownMonth -= 1;
    if (state.shownMonth < 0) {
      state.shownMonth = 11;
      state.shownYear -= 1;
    }
    state.selectedDay = 1;
    await loadCalendarForecast();
    renderForecastSummary();
    updateSelectedDate();
    renderCalendar();
  });
  document.querySelector('#nextMonth').addEventListener('click', async function () {
    state.shownMonth += 1;
    if (state.shownMonth > 11) {
      state.shownMonth = 0;
      state.shownYear += 1;
    }
    state.selectedDay = 1;
    await loadCalendarForecast();
    renderForecastSummary();
    updateSelectedDate();
    renderCalendar();
  });

  document.querySelector('#insertTemplate').addEventListener('click', function () {
    const notes = document.querySelector('#notes');
    notes.value = t('templateText');
    notes.focus();
  });
  document.querySelector('#chatForm').addEventListener('submit', sendChatMessage);
  document.querySelector('#exportDiary').addEventListener('click', exportDiary);
  document.querySelector('#exportBackup').addEventListener('click', exportBackup);
  document.querySelector('#importBackup').addEventListener('change', importBackup);
  document.querySelector('#clearChatHistory').addEventListener('click', clearChatHistory);
  document.querySelector('#finishOnboarding').addEventListener('click', function () { closeOnboarding(true); });
  document.querySelector('#skipOnboarding').addEventListener('click', function () { closeOnboarding(false); });
}

async function init() {
  bindEvents();
  if (state.authToken) {
    try {
      const user = await apiRequest('/api/auth/me');
      localStorage.setItem('sana-user-id', String(user.id));
      localStorage.setItem('sana-user-name', user.name);
    } catch (error) {
      if (error.status === 401) {
        state.authToken = '';
        ['sana-auth-token', 'sana-user-id', 'sana-user-name', 'sana-auth-expires'].forEach(function (key) { localStorage.removeItem(key); });
      }
    }
  }
  const savedModel = localStorage.getItem('sana-ollama-model');
  if (savedModel) document.querySelector('#ollamaModel').value = savedModel;
  savePreferences();
  updateAuthUI();
  fillLogForm(dateKey(today));
  applyLanguage(state.lang);
  await loadTrackerData();
  await loadChatHistory();
  maybeSendCycleNotification();
  if (!localStorage.getItem('sana-onboarding-done') && !state.periods.length && !isPregnancyMode()) setModal(onboardingModal, true);
  checkOllama();
}

